class C:
 def f(self): return 7
m=C().f
m.__func__.__dict__={"😀":7,"ω":9,"é":11,"a":13}
print(*dir(m)[-4:])

class C:
 def f(self): return 7
m=C().f
key="ta"+"g"
m.__func__.__dict__={key:7}
print([n for n in dir(m) if n=="tag"][0] is key)

class C:
 @classmethod
 def f(cls): return 7
m=C.f
m.__func__.tag=9
print("__func__" in dir(m),"tag" in dir(m),m(),m.__self__ is C)

class C:
 @staticmethod
 def f(): return 7
print("__code__" in dir(C.f),"__func__" in dir(C.f))

def read(self):
 print("dictionary")
 return {"tag":7}
class Callable: __dict__=property(read)
c=Callable()
m=classmethod(c).__get__(None,object)
print("tag" in dir(m))

def read(self): raise AttributeError("missing")
class Callable: __dict__=property(read)
c=Callable()
m=classmethod(c).__get__(None,object)
print(len(dir(m)))

def read(self): raise ValueError("original")
class Callable: __dict__=property(read)
c=Callable()
m=classmethod(c).__get__(None,object)
dir(m)

def read(self): raise KeyError("original")
class Callable: __dict__=property(read)
c=Callable()
m=classmethod(c).__get__(None,object)
dir(m)

def read(self): raise AttributeError("missing")
def fallback(self,name):
 print(name)
 return {"fallback":7}
class Callable: __dict__=property(read)
c=Callable()
m=classmethod(c).__get__(None,object)
Callable.__getattr__=fallback
print("fallback" in dir(m))

class Value:
 def __bool__(self): raise ValueError("never")
class Callable: __dict__=property(lambda self:Value())
c=Callable()
m=classmethod(c).__get__(None,object)
print(len(dir(m)))

class Callable: pass
c=Callable()
m=classmethod(c).__get__(None,object)
def lookup(self,name):
 if name=="__class__": raise ValueError("never")
 return object.__getattribute__(self,name)
Callable.__getattribute__=lookup
print(len(dir(m)))

